import hmac
import hashlib
import os
import time
import secrets
from flask import Flask, request, jsonify, session
from functools import wraps
import sqlite3
import bcrypt

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET_KEY', secrets.token_hex(32))

DB_PATH = '/tmp/auth_service.db'

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    db = get_db()
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        api_key_hash TEXT,
        role TEXT DEFAULT 'user',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS sessions (
        session_id TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        expires_at REAL NOT NULL,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )''')
    db.commit()
    db.close()

init_db()

def constant_time_compare(val1, val2):
    """Perform constant-time comparison to prevent timing attacks.
    Handles both string and bytes inputs safely."""
    if isinstance(val1, str):
        val1 = val1.encode('utf-8')
    if isinstance(val2, str):
        val2 = val2.encode('utf-8')
    if len(val1) != len(val2):
        # Still do a comparison to maintain constant time
        # but we know the result will be False
        hmac.compare_digest(val1, val1)
        return False
    return hmac.compare_digest(val1, val2)

def generate_api_token(user_id, api_key):
    """Generate a time-limited API token from user's API key."""
    timestamp = str(int(time.time()) // 300)  # 5-minute windows
    message = f"{user_id}:{timestamp}".encode('utf-8')
    expected = hmac.new(api_key.encode('utf-8'), message, hashlib.sha256).hexdigest()
    return expected

def verify_api_token(user_id, api_key, provided_token):
    """Verify an API token for the given user."""
    current_window = int(time.time()) // 300
    # Check current and previous window for clock skew tolerance
    for window_offset in [0, -1]:
        timestamp = str(current_window + window_offset)
        message = f"{user_id}:{timestamp}".encode('utf-8')
        expected = hmac.new(api_key.encode('utf-8'), message, hashlib.sha256).hexdigest()
        if constant_time_compare(provided_token, expected):
            return True
    return False

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        # Check session-based auth first
        if 'user_id' in session:
            db = get_db()
            user = db.execute('SELECT * FROM users WHERE id = ?', (session['user_id'],)).fetchone()
            db.close()
            if user:
                request.current_user = dict(user)
                return f(*args, **kwargs)

        # Check API token auth
        auth_header = request.headers.get('Authorization', '')
        if auth_header.startswith('Bearer '):
            token = auth_header[7:]
            # Token format: user_id:hmac_token
            parts = token.split(':', 1)
            if len(parts) == 2:
                try:
                    user_id = int(parts[0])
                    provided_token = parts[1]
                except (ValueError, IndexError):
                    return jsonify({'error': 'Invalid token format'}), 401

                db = get_db()
                user = db.execute('SELECT * FROM users WHERE id = ?', (user_id,)).fetchone()
                db.close()

                if user and user['api_key_hash']:
                    if verify_api_token(user_id, user['api_key_hash'], provided_token):
                        request.current_user = dict(user)
                        return f(*args, **kwargs)

        # Check X-API-Key header (direct key comparison)
        api_key = request.headers.get('X-API-Key', '')
        if api_key:
            provided_hash = hashlib.sha256(api_key.encode('utf-8')).hexdigest()
            db = get_db()
            users = db.execute('SELECT * FROM users WHERE api_key_hash IS NOT NULL').fetchall()
            db.close()

            for user in users:
                stored_hash = user['api_key_hash']
                if constant_time_compare(provided_hash, stored_hash):
                    request.current_user = dict(user)
                    return f(*args, **kwargs)

        return jsonify({'error': 'Authentication required'}), 401
    return decorated

def require_admin(f):
    @wraps(f)
    @require_auth
    def decorated(*args, **kwargs):
        if request.current_user.get('role') != 'admin':
            return jsonify({'error': 'Admin access required'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Username and password required'}), 400

    username = str(data['username']).strip()
    password = str(data['password'])

    if len(username) < 3 or len(username) > 50:
        return jsonify({'error': 'Username must be 3-50 characters'}), 400
    if len(password) < 8:
        return jsonify({'error': 'Password must be at least 8 characters'}), 400

    password_hash = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')

    try:
        db = get_db()
        db.execute('INSERT INTO users (username, password_hash) VALUES (?, ?)',
                   (username, password_hash))
        db.commit()
        db.close()
        return jsonify({'message': 'User registered successfully'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Username and password required'}), 400

    username = str(data['username']).strip()
    password = str(data['password'])

    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()
    db.close()

    if user and bcrypt.checkpw(password.encode('utf-8'), user['password_hash'].encode('utf-8')):
        session['user_id'] = user['id']
        return jsonify({'message': 'Login successful', 'user_id': user['id']}), 200

    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/api/generate-key', methods=['POST'])
@require_auth
def generate_key():
    new_key = secrets.token_hex(32)
    key_hash = hashlib.sha256(new_key.encode('utf-8')).hexdigest()

    db = get_db()
    db.execute('UPDATE users SET api_key_hash = ? WHERE id = ?',
               (key_hash, request.current_user['id']))
    db.commit()
    db.close()

    return jsonify({'api_key': new_key, 'message': 'Store this key securely, it cannot be retrieved again'}), 200

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    user = request.current_user
    return jsonify({
        'id': user['id'],
        'username': user['username'],
        'role': user['role'],
        'has_api_key': user['api_key_hash'] is not None
    }), 200

@app.route('/api/admin/users', methods=['GET'])
@require_admin
def list_users():
    db = get_db()
    users = db.execute('SELECT id, username, role, created_at FROM users').fetchall()
    db.close()
    return jsonify([dict(u) for u in users]), 200

